function validate([nums, queries]) {
  if (nums.length < 1 || nums.length > 10) return 'nums needs 1 to 10 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value of nums is between 0 and 1000.';
  if (queries.length < 1 || queries.length > 1000) return 'queries needs 1 to 1000 entries.';
  for (const query of queries) {
    if (query.length !== 3) return 'Each query is [l, r, val].';
    const [l, r, val] = query;
    if (!(0 <= l && l <= r && r < nums.length)) return 'Each query needs 0 <= l <= r < nums.length.';
    if (val < 1 || val > 10) return 'Each val is between 1 and 10.';
  }
  return null;
}

