function minZeroArray(nums, queries) {
  let answer = 0;
  for (let i = 0; i < nums.length; i++) {
    const target = nums[i];
    if (target === 0) {
      continue;
    }
    const reachable = new Array(target + 1).fill(false);
    reachable[0] = true;
    let needed = -1;
    for (let k = 0; k < queries.length; k++) {
      const [left, right, val] = queries[k];
      if (i < left || i > right) {
        continue;
      }
      for (let sum = target; sum >= val; sum--) {
        if (reachable[sum - val]) {
          reachable[sum] = true;
        }
      }
      if (reachable[target]) {
        needed = k + 1;
        break;
      }
    }
    if (needed === -1) {
      return -1;
    }
    answer = Math.max(answer, needed);
  }
  return answer;
}

