function minZeroArray(nums, queries) {
  // Try every prefix length k; for each element, list every total the covering queries can subtract.
  for (let k = 0; k <= queries.length; k++) {
    let allZero = true;
    for (let i = 0; i < nums.length && allZero; i++) {
      let totals = new Set([0]);
      for (let j = 0; j < k; j++) {
        const [l, r, v] = queries[j];
        if (l <= i && i <= r) totals = new Set([...totals, ...[...totals].map(t => t + v)]);
      }
      if (!totals.has(nums[i])) allZero = false;
    }
    if (allZero) return k;
  }
  return -1;
}

