function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 10 : int(1, 5);
  const q = size === 'large' ? 1000 : int(1, 8);
  const maxVal = size === 'large' ? 10 : (rand() < 0.5 ? 3 : 10);
  const queries = [];
  for (let j = 0; j < q; j++) {
    const l = int(0, n - 1);
    queries.push([l, int(l, n - 1), int(1, maxVal)]);
  }
  const cap = size === 'large' ? 1000 : 30;
  // Usually build nums from a hidden choice of positions among a prefix of the queries, so an answer exists.
  if (rand() < 0.75) {
    const prefix = int(1, q);
    const nums = new Array(n).fill(0);
    for (let j = 0; j < prefix; j++) {
      const [l, r, v] = queries[j];
      for (let i = l; i <= r; i++) if (rand() < 0.5 && nums[i] + v <= cap) nums[i] += v;
    }
    return [nums, queries];
  }
  const nums = Array.from({ length: n }, () => (rand() < 0.2 ? 0 : int(1, size === 'large' ? 1000 : 12)));
  return [nums, queries];
}
